<script src="/gg_app/plugins/AdminLTE-3.2.0/plugins/chart.js/Chart.min.js"></script>
<script>
$(function(){
 const colors={Draft:'#94a3b8',Approved:'#6d5dfc',Process:'#f3ad32',Pass:'#20b486',Fail:'#e85d75'}; let rows=[],erp={},charts={};

 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const pct=(a,b)=>b?((a/b)*100).toFixed(1)+'%':'-';
 function status(r){if((r.status==='Process'||r.was_in_process==1)&&erp[r.no_cp])return erp[r.no_cp].status;return r.status==='Prosess'?'Process':r.status;}
 function destroy(k){if(charts[k])charts[k].destroy()}
 function chart(k,id,type,data,opts={}){destroy(k);charts[k]=new Chart(document.getElementById(id),{type,data,options:Object.assign({responsive:true,maintainAspectRatio:false,legend:{position:'bottom'}},opts)});}
 function render(){
  const selectedStatus=$('#statusFilter').val(), dataRows=selectedStatus?rows.filter(r=>status(r)===selectedStatus):rows;
  const total=dataRows.length, creators={},groups={},counts={Draft:0,Approved:0,Process:0,Pass:0,Fail:0}; let approved=0,production=0;
  dataRows.forEach(r=>{let s=status(r);counts[s]=(counts[s]||0)+1;approved+=r.was_approved?1:0;production+=r.was_in_process?1:0;let c=creators[r.created_by]||(creators[r.created_by]={total:0,approved:0,prod:0,Pass:0,Fail:0});c.total++;c.approved+=r.was_approved?1:0;c.prod+=r.was_in_process?1:0;if(s==='Pass'||s==='Fail')c[s]++;let key=r.group_id||('w:'+r.kode_warna),g=groups[key]||(groups[key]={group_id:r.group_id,kode:r.kode_warna,warna:r.color_name,total:0,users:new Set(),Pass:0,Fail:0,last:''});g.total++;g.users.add(r.created_by);if(s==='Pass'||s==='Fail')g[s]++;if(r.created_at>g.last)g.last=r.created_at;});
  let final=counts.Pass+counts.Fail; const cards=[['Total Experiment',total,'Seluruh experiment','#6d5dfc'],['Draft',counts.Draft,'Belum disetujui','#94a3b8'],['Approved',counts.Approved,'Disetujui sebelum produksi','#6d5dfc'],['Process',counts.Process,'Sedang proses produksi','#f3ad32'],['Fail',counts.Fail,pct(counts.Fail,final)+' dari hasil final','#e85d75'],['Pass',counts.Pass,pct(counts.Pass,final)+' dari hasil final','#20b486']];
  $('#metrics').html(cards.map(c=>`<div class="col-6 col-lg-2 mb-3"><div class="metric" style="--accent:${c[3]}"><div class="metric-label">${c[0]}</div><div class="metric-value">${c[1]}</div><div class="metric-note">${c[2]}</div></div></div>`).join(''));
  chart('status','statusChart','doughnut',{labels:Object.keys(counts),datasets:[{data:Object.values(counts),backgroundColor:Object.keys(counts).map(x=>colors[x]||'#64748b'),borderWidth:0}]},{cutoutPercentage:68});
  chart('funnel','funnelChart','horizontalBar',{labels:['Total','Approved','Process','Hasil Final','Fail','Pass'],datasets:[{data:[total,approved,production,final,counts.Fail,counts.Pass],backgroundColor:['#334155','#6d5dfc','#f3ad32','#19b9d2','#e85d75','#20b486'],borderWidth:0}]},{legend:{display:false},scales:{xAxes:[{ticks:{beginAtZero:true}}]}});
  let daily={},period=$('#trendPeriod').val();dataRows.forEach(r=>{let d=r.created_at.slice(0,10),key=d;if(period==='month')key=d.slice(0,7);else if(period==='week'){let dt=new Date(d+'T00:00:00'),day=(dt.getDay()+6)%7;dt.setDate(dt.getDate()-day);key='Minggu '+dt.toISOString().slice(0,10)}daily[key]=(daily[key]||0)+1});let trendLabel=period==='day'?'Experiment per Hari':period==='week'?'Experiment per Minggu':'Experiment per Bulan';chart('trend','trendChart','line',{labels:Object.keys(daily),datasets:[{label:trendLabel,data:Object.values(daily),borderColor:'#6d5dfc',backgroundColor:'rgba(109,93,252,.12)',pointBackgroundColor:'#6d5dfc',lineTension:.25,fill:true}]},{legend:{display:false},scales:{yAxes:[{ticks:{beginAtZero:true,precision:0}}]}});
  let creatorList=Object.entries(creators).sort((a,b)=>b[1].total-a[1].total);chart('creator','creatorChart','horizontalBar',{labels:creatorList.slice(0,10).map(x=>x[0]),datasets:[{label:'Total Experiment',data:creatorList.slice(0,10).map(x=>x[1].total),backgroundColor:'#19b9d2'}]},{legend:{display:false},scales:{xAxes:[{ticks:{beginAtZero:true,precision:0}}]}});
  $('#creatorRows').html(creatorList.map(([u,c])=>`<tr><td><b>${esc(u)}</b></td><td class="text-center">${c.total}</td><td class="text-center">${c.approved}</td><td class="text-center">${c.prod}</td><td class="text-center text-success">${c.Pass}</td><td class="text-center text-danger">${c.Fail}</td><td class="text-center"><b>${pct(c.Pass,c.Pass+c.Fail)}</b></td></tr>`).join('')||'<tr><td colspan="7" class="text-center text-muted">Tidak ada data</td></tr>');
  $('#trialRows').html(Object.values(groups).sort((a,b)=>b.total-a.total).slice(0,5).map(g=>`<tr><td><b>${esc(g.kode)}</b><div class="text-muted small">${esc(g.warna)}</div></td><td class="text-center"><b>${g.total}</b></td><td class="text-center">${g.users.size}</td><td class="text-center"><span class="text-success">${g.Pass}</span> / <span class="text-danger">${g.Fail}</span></td><td>${g.group_id?`<a class="btn btn-xs btn-outline-primary" href="../view_group.php?group_id=${g.group_id}"><i class="fas fa-eye"></i></a>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="text-center text-muted">Tidak ada data</td></tr>');
 }
 async function loadErp(cp){erp={};let done=0;$('#erpText').text(cp.length?'Memuat status ERP 0 / '+cp.length:'Tidak ada No CP untuk diperiksa');$('#erpProgress').css('width',cp.length?'0%':'100%');for(let i=0;i<cp.length;i+=250){let batch=cp.slice(i,i+250);try{let res=await $.ajax({url:'ajax_erp_status.php',method:'POST',data:{cp:batch}});Object.assign(erp,res.data||{});}catch(e){$('#erpText').text('Status ERP belum lengkap. Data dasar tetap tersedia.');return render();}done+=batch.length;$('#erpText').text('Memuat status ERP '+done+' / '+cp.length);$('#erpProgress').css('width',(done/cp.length*100)+'%');render();}if(cp.length)$('#erpText').text('Status ERP lengkap · '+cp.length+' No CP diperiksa');}
 function load(){let q={date_from:$('#dateFrom').val(),date_to:$('#dateTo').val()};$('#erpText').text('Memuat data dasar...');$.getJSON('dashboard_data.php',q).done(res=>{rows=res.data||[];render();loadErp(res.cp||[])}).fail(xhr=>Swal.fire('Error',xhr.responseJSON?.message||'Dashboard gagal dimuat','error'));}
 $('#trendPeriod,#statusFilter').change(render);$('#filterBtn').click(load);$('#resetBtn').click(()=>{$('#dateFrom,#dateTo,#statusFilter').val('');$('#trendPeriod').val('day');load()});load();
});
</script>

